INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('descent-ii', 668, '1996-03-13', 92, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ye1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfyy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Descent II', 'You''re going down... again. If you thought Descent went to the edge of 360° 3D power-blasting sensory insanity, then prepare yourself. You''re about to plunge over the edge, and into the depths of Descent II. Suddenly warped into the outer reaches of the Zeta Aquilae System, your new mission sends you into the black depths of treacherous alien mines. You blast through enemy robots with powerful new tools, leaving their flaming hulks in your exhaust. Your ultimate goal: to exterminate the alien robot stronghold from the enemy Alien Base and claim total control -- it''s 30 new levels of outrageous destruction. But this time, you''re not alone. Joining you on your deadly new assignment is your loyal Guide-bot. This faithful companion rushes with you through the twists and turns of the menacing darkness, often scouting ahead to hunt down the orbs, powerups and tools you desperately need to complete your job. But beware -- raging enemies are still determined to destroy you, including the menacing Thief-bot who''s set on stealing your weapons of destruction and precious powerups. Get ready -- Descent II is about to take you on a whole new synapse-smashing ride.' FROM games WHERE igdb_id = 668 ON CONFLICT (game_id, language_code) DO NOTHING;
