INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Don''t Know Jack Sports', 'Think you know everything about football, basketball, baseball, or hockey? How about tennis, volleyball, golf, or lawn darts? Then light up the scoreboard with You Don''t Know Jack Sports, YDKJ all hopped up on ''roids! So put in your mouthguard, adjust your cup, and get ready. Play ball… er, trivia!' FROM games WHERE igdb_id = 16786 ON CONFLICT (game_id, language_code) DO NOTHING;
