INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-smurfs-travel-the-world', 4402, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dsj.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Smurfs Travel the World', 'Night falls at the Smurf Village. Inquisitive Smurf brings Smurfette along to Papa Smurf''s laboratory to see the Magic Crystal that allows them to travel to anywhere in the world, but suddenly Smurfette breaks it, and they are gone! Now they must face the challenges in all continents in order to retrieve all shards of the Crystal and return home. (In the Master System and the portable versions of this game, there is also the additional task of cleaning the various regions of the world that the two Smurfs visit of its pollution.)' FROM games WHERE igdb_id = 4402 ON CONFLICT (game_id, language_code) DO NOTHING;
