INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('death-rally', 665, '1996-09-06', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2f2r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2zpq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Rally', 'Shoot your way through screaming bystanders, pick up more ammo and turbo from the side of the track, and floor the pedal while performing some shady deals for The Dealer. No trick is too dirty when you''re preparing for The Final Confrontation. Only the hardest armor, the most powerful engine and the biggest guns will see you through the ultimate battle against The Adversary. And when you feel you can''t take it anymore, you can check out the underground market: Spiked bumpers, landmines, rocket fuel or sabotage can provide a way to create some nasty accidents for the competition. Death Rally was remade for IOS and Android in 2012, by fellow Finnish company Mountain Sheep. Remedy Entertainment stayed on board with the publishing.' FROM games WHERE igdb_id = 665 ON CONFLICT (game_id, language_code) DO NOTHING;
