INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('afterlife', 175, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5nrs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dcd0decc7glk3vylvwd8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Afterlife', 'Telling people where to go is just the beginning. Welcome to Afterlife, a world-building simulation that lets you create the hereafter in the here and now. Possessed of an unearthly sense of humor, it all begins in a god-knows-where galaxy. As a "regional spiritual director" your task, given to you by the Powers That Be, is to develop two prime planes of “unreal estate” - heaven and hell - simultaneously. Keep the billions of souls happy by giving them the rewards and punishments they deserve. The wages of sin are plentiful. Open up your afterlife with the Pearly Gates of Heaven or the Fiery Gates of Hell, zone for the Seven Deadly Sins and/or their respective Virtues. Then lay down some roads. Soon, the dearly departed arrive in droves. Keep them in your afterlife and you flourish. Lose too many along the way and it may mean a visit from the Four Surfers of the Apocalypso (not a good time). Factor in a half-dozen or so supernatural disasters (not including total annihilation), money problems and headaches from the planet and you''re in for infinite hours of gameplay.' FROM games WHERE igdb_id = 175 ON CONFLICT (game_id, language_code) DO NOTHING;
