INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War Wind', 'War Wind allows you to view this epic struggle through the eyes of four unique races, each with its own strengths, weaknesses and distinctive A.I. A real-time strategy masterwork, War Wind features 28 read-to-play scenarios. A powerful Scenario Editor that allows you to place units and build new battles. And a story of such compelling depth you won''t believe it''s just a game.' FROM games WHERE igdb_id = 929 ON CONFLICT (game_id, language_code) DO NOTHING;
