INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-mario-64', 1074, '1996-06-23', 89, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co721v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1gev.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario 64', 'Mario is super in a whole new way! Combining the finest 3-D graphics ever developed for a video game and an explosive soundtrack, Super Mario 64 becomes a new standard for video games. It''s packed with bruising battles, daunting obstacle courses, and underwater adventures. Retrieve the Power Stars from their hidden locations and confront your arch-nemesis— Bowser, King of the Koopas! • Run freely in a grassy meadow, tip-toe through a gloomy dungeon, climb to the top of a mountain, or take a swim in the moat! • Leap headfirst into a watery painting and soon you''ll be searching for the surface in an underwater realm! • On-the-fly, 3-D rendered gameplay delivers the action of ruthless enemy attacks from every angle! • Find the Caps that give Mario super powers and ponder the mysteries of the pyramid; you can even race Koopas for fabulous prizes! • With the Nintendo 64 Controller and its analog Control Stick, Mario can crawl, kick down obstacles, swim, do reverse flips, and even stick the landing on his backwards somersault! • Saved game information is stored for up to four players in memory.' FROM games WHERE igdb_id = 1074 ON CONFLICT (game_id, language_code) DO NOTHING;
