INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sonic-wings-special', 44837, '1996-07-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4sqy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3sh4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Wings Special', 'Sonic Wings Special is a 1996 vertical-scrolling shoot ''em up that combines the features in Sonic Wings, Sonic Wings 2, and Sonic Wings 3. It was ported to arcade as Sonic Wings Limited. The home console version adds new characters and endings, new bosses, updated graphics and unlockable planes. There are also Time Attack and 2-player modes. The game uses a branching stage system, so it is impossible to see all levels in one sitting. There is a total of 14 playable characters and many different endings (some of which are reused from previous games in the series). Overall the game has a comic feel. As of Summer 2012, the Android version of Sonic Wings Special has only 4 playable characters with 4 endings and 9 stages. However, the publisher is planning to add further elements of the original version.' FROM games WHERE igdb_id = 44837 ON CONFLICT (game_id, language_code) DO NOTHING;
