INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood Omen: Legacy of Kain', 'Blood Omen: Legacy of Kain is a top-down action-adventure video game with role-playing game elements. It is the first game in the Legacy of Kain series, and the only one developed by Silicon Knights and published by Crystal Dynamics. The game was first released in 1996 for the PlayStation, and later ported to Microsoft Windows. A Sega Saturn version was announced during production but later cancelled before release. It was followed by four sequels, which were all developed by Crystal Dynamics and published by Eidos Interactive.' FROM games WHERE igdb_id = 7894 ON CONFLICT (game_id, language_code) DO NOTHING;
