INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nights-into-dreams-dot-dot-dot--1', 5075, '1996-07-05', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2n17.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/argry.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nights Into Dreams...', 'The story follows the teenagers Elliot Edwards and Claris Sinclair, who enter Nightopia, a dream world where all dreams take place. With the help of Nights, an exiled "Nightmaren", they begin a journey to stop the evil ruler Wizeman from destroying Nightopia and consequently the real world. Players control Nights flying through Elliot and Claris''s dreams to gather enough energy to defeat Wizeman and save Nightopia. The game is presented in 3D and imposes time limits on every level, in which the player must accumulate points to proceed.' FROM games WHERE igdb_id = 5075 ON CONFLICT (game_id, language_code) DO NOTHING;
