INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('penny-racers--1', 133238, '1996-03-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9kyq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scixjv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penny Racers', 'Penny Racers (released as Choro Q in Japan) is a 1996 racing video game developed by Tamsoft and published by Takara for the PlayStation. Sony Computer Entertainment released the game in PAL regions. The game features cars based on Takara''s line of miniature Choro Q / Penny Racers toys, and was the first game based on Choro Q released outside Japan since Taito''s 1984 title on MSX. Screech along tarmac raceways, slide around icy corners in the winter sections, or skid around dirt tracks in the rally courses. Squished up versions of real-life cars plus a split screen mode for frantic two player road duels.' FROM games WHERE igdb_id = 133238 ON CONFLICT (game_id, language_code) DO NOTHING;
