INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Emblem: Seisen no Keifu', 'Fire Emblem: Genealogy of the Holy War is a Japanese Super Famicom tactical role-playing game developed by Intelligent Systems and published by Nintendo. It was released on May 14, 1996 in Japan. It is the fourth title in the Fire Emblem series, the second Fire Emblem title for the Super Famicom, and the last game produced by the late Gunpei Yokoi. It was released on the Japanese Virtual Console service on January 30, 2007. The game was originally to be titled as Fire Emblem: Light Inheritors.' FROM games WHERE igdb_id = 1436 ON CONFLICT (game_id, language_code) DO NOTHING;
