INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stargunner', 19379, '1996-11-19', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4wnu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4aqp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stargunner', 'In the far distant future, an epic war for survival takes place... Deep within the Andromeda galaxy, the people of Zile grow restless and greedy. The Zilions secretly prepare for a massive strike against the nearby planet Ytima. Fearing such an attack, the Ytimians train an elite squad of "Stargunners." Their mission: To strike the planet Zile and cripple the Zilions’ three strongholds, where the Zilion war fleets await. If the Stargunners can surprise the Zilions on their own planet and wipe out their fleet, then good will triumph over evil once again.' FROM games WHERE igdb_id = 19379 ON CONFLICT (game_id, language_code) DO NOTHING;
