INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guardian Heroes', 'Guardian Heroes is a 2D side-scrolling beat ''em up video game with RPG elements developed by Treasure and released in 1996 for the Sega Saturn. A band of young adventurers begin a quest to change the fate of their kingdom after an enchanted sword falls into their hands. Players may choose between four characters, each with their own unique fighting style, and embark on many different paths in the game''s story mode. The game also includes a special versus mode wherein up to six players can compete against each other in arena combat.' FROM games WHERE igdb_id = 21838 ON CONFLICT (game_id, language_code) DO NOTHING;
