INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abuse', 'Abuse resembles a side-scrolling platform game. The game is marked for its unusual control scheme: The keyboard is used to move Nick, while the mouse is used for aiming the weapons. The basic gameplay consists of fighting various enemies (mostly the various forms of mutants, who prefer to attack in huge swarms) and solving some simple puzzles, most involving switches.' FROM games WHERE igdb_id = 586 ON CONFLICT (game_id, language_code) DO NOTHING;
