INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Pocahontas', 'Disney''s Pocahontas is a platform game based on the film of the same name. The Sega Genesis/Mega Drive version was developed by Funcom Oslo on contract with Disney and was released on January 1, 1996. It was followed by a later version for the Game Boy developed by Tiertex Design Studios and released on June 10, 1996, nearly a year after the film''s premiere' FROM games WHERE igdb_id = 24979 ON CONFLICT (game_id, language_code) DO NOTHING;
