INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest Moon', 'Ever wanted to live life on a farm, with nothing but the sun, the fresh scent of your crops, the muddy fields underneath, and cows and chickens to keep you company? Well, you''re in luck, because you have just inherited your grandfather''s ranch, but it''s in a terrible state of disrepair! What ever can you do?' FROM games WHERE igdb_id = 3376 ON CONFLICT (game_id, language_code) DO NOTHING;
