INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Toon Adventures: The Great Beanstalk', 'Tiny Toon Adventures: Buster and the Beanstalk is the only Tiny Toon Adventures-related video game released. Buster and the Beanstalk is a retelling of the Jack and the Beanstalk story starring Tiny Toon Adventures characters. The object of the game is to help two stars from the show, Buster Bunny and Plucky Duck, get into the Giant''s castle.' FROM games WHERE igdb_id = 8054 ON CONFLICT (game_id, language_code) DO NOTHING;
