INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mortal Kombat Trilogy', 'Mortal Kombat Trilogy features the same gameplay and story as Mortal Kombat 3, but adds characters and stages from the other three arcade games, including Ultimate Mortal Kombat 3. Some completely new characters were also introduced. New additions to the game included the "Aggressor" bar, a meter that fills during the course of the match and temporarily makes a player character faster and stronger. It also features the Brutality, a long combination of attacks that ends with the opponent exploding.' FROM games WHERE igdb_id = 4121 ON CONFLICT (game_id, language_code) DO NOTHING;
