INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AH-64D Longbow', 'AH-64D Longbow is a realistic combat flight simulator of the AH-64D Apache Longbow attack helicopter. Released on June 3, 1996, for the PC, this simulation was developed at Origin Systems. AH-64D Longbow was the second simulator released under the Jane''s Combat Simulators line from Electronic Arts.' FROM games WHERE igdb_id = 592 ON CONFLICT (game_id, language_code) DO NOTHING;
