INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wild Arms', 'Wild Arms is a Western-themed role-playing video game developed by Japanese software company Media.Vision. Originally released in Japan in 1996 for the Sony PlayStation video game console, it was later translated and released in North America in 1997 and Europe in 1998 by Sony Computer Entertainment. It is noteworthy for not only being one of the first role-playing video games on the PlayStation, but also one of the few to feature a Western American setting and motif. The game features 2D computer graphics for normal gameplay, while battle sequences are rendered in 3D.' FROM games WHERE igdb_id = 1677 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 1677 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
