INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes of Might and Magic II: The Succession Wars', 'Heroes of Might and Magic II: The Succession Wars is a turn-based strategy video game developed by Jon Van Caneghem through New World Computing and published in 1996 by the 3DO Company. The game is the second installment of the Heroes of Might and Magic series and is typically credited as the breakout game for the series. Heroes II was voted the sixth-best PC game of all time by PC Gamer in May 1997.' FROM games WHERE igdb_id = 363 ON CONFLICT (game_id, language_code) DO NOTHING;
