INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marvel-super-heroes-in-war-of-the-gems', 42656, '1996-11-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3b7l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xgkmwawtdezxkvwukjdc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Super Heroes in War of the Gems', 'The most powerful collection of Marvel Super Heroes now unite to battle treacherous mobs of Super-Villians! A mysterious foe has kicked off his plan to rule the world by collecting the Infinity Gems. While each gem controls one force of nature, combined they command limitless power. The fate of the entire world depends on your ability to defeat this sinister scheme before the gems are combined. Master the brute strength of your favorite hero to take on this life and death challenge. You choose the hero best suited to each mission and control all the action, like breaking barriers with the Incredible Hulk or tackling challenges with Spider-Man''s webs and climbing ability. It''s an incredible action-adventure demanding skill, cunning and reflexes to defeat a diabolical plot and the most amazing assortment of corrupt Super-Villains ever assembled.' FROM games WHERE igdb_id = 42656 ON CONFLICT (game_id, language_code) DO NOTHING;
