INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Corpse-Party', 'A group of friends unknowingly perform an occult ritual that traps them in an otherworldly elementary school. Here, the vengeful spirits of young children threaten their lives and their sanity, and the only hope of survival is to uncover the chilling details behind the murders of those trapped before them...' FROM games WHERE igdb_id = 148220 ON CONFLICT (game_id, language_code) DO NOTHING;
