INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sonic-3d-blast', 9476, '1996-11-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2v74.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar30it.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic 3D Blast', 'Sonic 3D Blast is a 1996 platform video game developed by Traveller''s Tales and Sonic Team, and published by Sega for the Genesis, Saturn, and Windows. Part of the Sonic the Hedgehog series, the game abandons previous Sonic games'' side-scrolling style in favor of isometric gameplay, making use of some pre-rendered 3D models converted into sprites. The game features creatures known as Flickies, which first appeared in the 1984 arcade game Flicky. Controlling only Sonic himself, the player''s goal is to collect Flickies and carry them to safety, periodically sparring with the series antagonist Dr. Robotnik, who is imprisoning them within robots.' FROM games WHERE igdb_id = 9476 ON CONFLICT (game_id, language_code) DO NOTHING;
