INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Settlers II: Veni, Vidi, Vici', 'The Settlers II: Veni, Vidi, Vici is a real-time strategy computer game, released by Blue Byte Software in 1996. Its gameplay is very similar to that of its predecessor, The Settlers, albeit with a Roman theme and improved graphics. It is the second game in The Settlers series. Many fans of the franchise consider this the best game of the series, primarily because future instalments changed the transport management aspect considerably. This popularity encouraged Blue Byte to publish a remake of the game, The Settlers II (10th Anniversary) for Windows and release a port of the original game on Nintendo DS.' FROM games WHERE igdb_id = 2596 ON CONFLICT (game_id, language_code) DO NOTHING;
