INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wing-commander-iv-the-price-of-freedom', 934, '1996-02-12', 63, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2khv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21n2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wing Commander IV: The Price of Freedom', 'Wing Commander 4 is one of the greatest space sims of all time, and some even consider it the greatest one of all. It is one of those games that did everything right. This is one of the few games that actually successfully manages to integrate a lot of FMV into the action, mostly because it uses trained film actors and directors. The combat is straightforward, fluid, and entertaining. The characters are as believable and memorable as they come. The orchestrated music -- just perfect. Finally, its enthralling story is both deep and plausible -- a combination that is often lost in modern games. There is simply no reason not to play this game and, once you do start playing, you will find it hard to think of a reason why you should stop.' FROM games WHERE igdb_id = 934 ON CONFLICT (game_id, language_code) DO NOTHING;
