INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-elder-scrolls-ii-daggerfall', 53, '1996-08-31', 89, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yan.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1m3m.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Elder Scrolls II: Daggerfall', 'The Elder Scrolls - Daggerfall is the second fantasy RPG from The Elder Scrolls series. The game is situated in a city of Daggerfall and its surrounding areas. The emperor himself asked you, as your friend, to investigate the death of King Lysandus. The whole story is up to you. There is no straight line which you should follow. you have a number of options for character classes and numerous regions filled with cities, towns, and dungeons. Your journey starts on your way to the Kingdom of Daggerfall. Unfortunately your ship is wrecked in a storm and you end up in a small cave with only your bare life. Your first goal becomes to escape, and so your adventure begins. The game has a numerous options how to solve the crisis and numerous differed endings as well.' FROM games WHERE igdb_id = 53 ON CONFLICT (game_id, language_code) DO NOTHING;
