INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('san-francisco-rush-extreme-racing', 3595, '1996-12-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fs8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ba5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'San Francisco Rush: Extreme Racing', 'San Francisco Rush: Extreme Racing is the first game in the Rush series. Tne N64 version contains six regular tracks and two hidden tracks. The regular tracks can be run in either reverse or mirrored modes and feature added collectible hidden keys throughout the track that can be used to unlock hidden vehicles. It also contains a Practice Mode and a Death Race mode where the game ends if the player crashes. The N64 port of Rush also includes a Circuit Mode and a save system for Fast Times, circuit progress, and hidden keys that the player can find on secret spots to unlock new cars.' FROM games WHERE igdb_id = 3595 ON CONFLICT (game_id, language_code) DO NOTHING;
