INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('creatures', 11370, '1996-11-01', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21ya.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scb1cy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Creatures', 'Discover a large, living landscape - the surface a world called Albia. You exist in this world only as a virtual presence, a sort of remote-control existence, which the computer portrays as a hand-shaped mouse cursor. In this world are a range of locations and strange creatures, related loosely (and with considerable poetic license) to Northern myth. You begin near to the long-abandoned home of a family of Norns (small furry creatures), where a few eggs, languishing in a broken-down incubator, are almost all that remains of the Nornir race.' FROM games WHERE igdb_id = 11370 ON CONFLICT (game_id, language_code) DO NOTHING;
