INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SimPark', 'Another of the "spin-offs" in the Sim franchise by Maxis. Aimed moreso at children, SimPark''s objective is to cultivate and manage a successful park and could be considered a toned down version of SimIsle.' FROM games WHERE igdb_id = 16613 ON CONFLICT (game_id, language_code) DO NOTHING;
