INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('freddi-fish-and-luthers-water-worries', 17296, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3zxp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ars05.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freddi Fish and Luther''s Water Worries', 'Dive in to help Freddi Fish and Luther keep the ocean from draining and save the sea creatures! Luther’s got to pop an ocean full of air bubbles before they make it to the surface. A souped-up slingshot, a little fancy finwork and some help from you are all he’ll need! Sea sponges, boulders and teleporting whirlpools are some of the useful tools you’ll need to succeed. Stinging jellyfish, spraying octopi and smelly seaweed are the least of Luther’s Water Worries. Challenging, arcade-style games for kids ages 3 to 8 (and children of all ages) Brand new action with all the quality you’d expect from Humongous Entertainment Save your game after each level and track the scores of up to 75 players Two-player mode allows Freddi Fish to get in on the action Over 100 levels of fin-flapping fun.' FROM games WHERE igdb_id = 17296 ON CONFLICT (game_id, language_code) DO NOTHING;
