INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Johnny Bazookatone', 'The original guitar hero with the Elvis attitude and purple hair pompadour, Johnny Bazookatone, has been imprisoned in the year 2050 in Sin Sin Prison by El Diablo, the Lord of the Underworld, who is jealous of his talent and kidnaps other musical legends as well in this 3D side-scrolling platformer. Johnny''s guitar Anita has been taken from him and he sets out to escape and vanquish foes on his way to be reunited with Anita.' FROM games WHERE igdb_id = 4256 ON CONFLICT (game_id, language_code) DO NOTHING;
