INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Gladiator Episode I: Final Crusade', 'Star Gladiator Episode I: Final Crusade is a 1996 weapon-based 3D fighting game released by Capcom for the PlayStation-based ZN-1 arcade hardware. It was Capcom‍ ''​s first polygonal fighting game, preceding the original Street Fighter EX (which Capcom had co-produced with Arika) by a few months A PlayStation port was released in October 1996. It was followed by a single sequel, Plasma Sword, in 1998.' FROM games WHERE igdb_id = 14680 ON CONFLICT (game_id, language_code) DO NOTHING;
