INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('true-love-story', 137873, '1996-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9pny.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'True Love Story', 'True Love Story is a visual novel styled love simulation game where the protagonist meets many girls and has one month''s time to make one of them fall in love with him. The player moved to a new town and is living with his younger sister. The story progresses in a typical visual novel style where one reads onscreen text, talks to present characters and moves from location to location in a determined order. Free movement is not done directly on a map but is rather scheduled. During school and lunch breaks the player can schedule places on school campus he wishes to visit, and after school additional scheduling of the place around the town can be selected. Depending on place one visits, the location will have different girls to talk to, or if noone and the player will soon leave the place without engaging in any dialogue with anyone.' FROM games WHERE igdb_id = 137873 ON CONFLICT (game_id, language_code) DO NOTHING;
