INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tex Murphy: The Pandora Directive', 'It''s April 2043 and you- as Tex Murphy, the last of the old-style gumshoes- find yourself racing against time in the most dangerous game of your life. What is the truth behind the rumored UFO crash at Roswell, New Mexico? Why did the military suddenly shut down and seal off the Roswell complex? And why the frequent references to the lost Mayan civilization?' FROM games WHERE igdb_id = 17424 ON CONFLICT (game_id, language_code) DO NOTHING;
