INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jet-moto', 20717, '1996-11-13', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa05e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7k6o.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jet Moto', 'Gameplay in the Jet Moto series differs from traditional racing games, as players instead control hoverbikes which hover close above the ground and can be driven over both land and water. Most of the courses in the games are designed to take advantage of this ability. The game has a variant of the traditional road course but also introduces a new course type, known as a suicide course. Instead of being a continuous loop, these tracks have checkpoints at either end of the course, and the starting grid in the centre. Characters race to one end, then turn around to head for the other checkpoint, repeating the process until all laps are complete. This provides a new gameplay dynamic as often the player must navigate oncoming traffic. Characters are split into teams, and bikes are adorned with logos of products such as Mountain Dew and Butterfinger, similar to real-life sponsored racing.' FROM games WHERE igdb_id = 20717 ON CONFLICT (game_id, language_code) DO NOTHING;
