INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clock Tower', 'Clock Tower, known as Clock Tower 2 in Japan, is a PlayStation point-and-click survival horror game and a sequel to Clock Tower: The First Fear. One year after the events of Clock Tower: The First Fear, in late 1996, Jennifer Simpson has been adopted by Helen Maxwell, the assistant of a renowned psychiatrist, Samuel Barton, and is currently undergoing treatment at a university research building in Oslo, Norway, to help her cope with her traumatic experiences in the Clock Tower case and possibly shed some light on the mystery that was the Scissorman.' FROM games WHERE igdb_id = 19287 ON CONFLICT (game_id, language_code) DO NOTHING;
