INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SimCopter', 'SimCopter lets players explore SimCity 2000 environments from a helicopter pilot''s perspective. Players respond to various emergencies across custom or pre-made cities, including fires, bank robberies, and medical evacuations. The game integrates with emergency services, allowing players to coordinate with police, fire departments, and ambulances while completing missions in their aircraft.' FROM games WHERE igdb_id = 1496 ON CONFLICT (game_id, language_code) DO NOTHING;
