INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokyo Highway Battle', 'Players navigate through three Tokyo highway circuits driving one of 72 high-performance sports cars. While driving, players earn valuable points which are used to purchase upgrade parts for their vehicle. To ensure the most realistic gameplay, developers Bullet-Proof Software, enlisted the guidance of racing champion, Keiichi Tsuchiya and automotive specialist, Masaaki Bando Under their supervision, Bullet-Proof painstakingly recreated the physics and handling of each race car. The Saturn release, only released in Japan, included many more videos and starred the Drift King himself through these cutscenes.' FROM games WHERE igdb_id = 20797 ON CONFLICT (game_id, language_code) DO NOTHING;
