INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('killer-instinct-gold', 10613, '1996-11-25', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25wb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/z7rhm1xdfisoidpjnec7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killer Instinct Gold', 'Rare was a prominent second-party developer for Nintendo, and produced the Killer Instinct series exclusively for the company as their response to Mortal Kombat. Following the success of the 1995 Killer Instinct port for the Super Nintendo home console, Rare began a sequel for the same console. They transitioned development to the Nintendo 64 upon its announcement. Gold was scheduled as a launch title for the new console but was delayed until its North American release in November 1996. It received a wider release in May 1997. It was also included in Rare''s 2015 Xbox One retrospective compilation, Rare Replay.' FROM games WHERE igdb_id = 10613 ON CONFLICT (game_id, language_code) DO NOTHING;
