INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Formula 1', 'Formula 1 features the tracks, cars, advertising and excitement from the 1996 Formula 1 season. Murray Walker provides the commentary in his unique style. Players choose from thirty drivers with an abundance of options before even heading out onto the track. Options include weather conditions, arcade or Grand Prix modes, car dynamics, skill level, and number of rounds.' FROM games WHERE igdb_id = 8294 ON CONFLICT (game_id, language_code) DO NOTHING;
