INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quake', 'Quake is a first-person shooter video game, developed by id Software and published by GT Interactive in 1996 and featured music composed by Trent Reznor and Nine Inch Nails. It is the first game in the popular Quake series. In the game, players must find their way through various maze-like, medieval environments while battling a variety of monsters using a wide array of weapons.' FROM games WHERE igdb_id = 333 ON CONFLICT (game_id, language_code) DO NOTHING;
