INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MechWarrior 2: Mercenaries', 'MechWarrior 2: Mercenaries was released in September 1996 and is a stand-alone sequel to MechWarrior 2 and the last Activision BattleTech game. In this game, the player takes control of an Inner Sphere mercenary squad, with control over the finances and mission selections. Mercenaries gives the player access to 30 new BattleMechs and 50 missions covering numerous worlds, including missions pertaining to the Clan invasion. Mercenaries also features MercNet (a redesign of NetMech) for multiplayer.' FROM games WHERE igdb_id = 785 ON CONFLICT (game_id, language_code) DO NOTHING;
