INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tunnel-b1', 12900, '1996-10-04', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30fu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1lvd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tunnel B1', 'Prepare yourself for dangerous underground combat action in TUNNEL B1 for the PlayStation. Command your specialized B1 hovercraft in fierce battles, as you attempt to bring down an evil madman intent on detonating a thermonuclear explosion and destroying the world. Traverse dark and ominous caverns, dank sewers, and winding tunnels at super speeds while blasting enemies and collecting hidden power-ups. Compete in frenzied, timed races against frightening drones which you must hunt down and eliminate, and fight fast helicopters and steel-hardened tanks determined to bring about your demise. Use all the weapons in your deadly arsenal including standard guns, powerful rockets, blistering lasers, flares and mines to do your job. You''ll have to take out entrenched enemy gun turrets, unlock security doors to reach new and tougher stages, explore vast subterranean environments, and avoid devious traps in an intense quest to save humankind. In TUNNEL B1 only you and your gaming skills stand in the way of certain destruction.' FROM games WHERE igdb_id = 12900 ON CONFLICT (game_id, language_code) DO NOTHING;
