INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Fighter Alpha 2', 'Street Fighter Alpha 2 is both a sequel and a remake to the previous year''s Street Fighter Alpha: Warriors'' Dreams. The game features a number of improvements over the original, such as new attacks, stages, endings, and gameplay features. New characters in this version include Gen, Rolento and Sakura. Dhalsim and Zangief also return to the fight with some new moves.' FROM games WHERE igdb_id = 6703 ON CONFLICT (game_id, language_code) DO NOTHING;
