INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tecmo''s Deception: Invitation to Darkness', 'Should you enter Tecmo''s Deception you should be warned! You must decide who lives and who dies. As in life, Tecmo''s Deception will hold you responsible for your actions. Everything you do, everywhere you go, everyone you meet has a reason. Are you seeking revenge, resurrection, or redemption? It''s your decision.' FROM games WHERE igdb_id = 20801 ON CONFLICT (game_id, language_code) DO NOTHING;
