INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RayStorm', 'RayStorm is a scrolling shooter set hundreds of years in the future, and was one of the launch titles for the Sony PlayStation. RayStorm consists of eight stages where players must pilot their "R-Gray" spaceships shooting down anything that moves. Like all of the games in the Ray Series, enemies can be shot down with a primary weapon or by holding down a missile button to lock on to multiple enemies.' FROM games WHERE igdb_id = 45089 ON CONFLICT (game_id, language_code) DO NOTHING;
