INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('donkey-kong-country-3-dixie-kong-s-double-trouble', 1094, '1996-11-18', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co217n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1t8q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong Country 3: Dixie Kong''s Double Trouble!', 'Monkey Mayhem Lives On! Kiddy Kong is a portly primate toddler with incredible power and agility! He teams up with Dixie Kong to stop the ever-present army of Kremlings. The game play and ACM graphics just keep getting better in this visually stunning installment in one of the most popular video game series of all time! Combining their unique abilities as they throw each other into action, Dixie Kong and Kiddy Kong set off to rescue Diddy Kong and Donkey Kong. Collect tons of treasure, grab billions of bananas and find more secret stuff than you''ve ever seen (or not seen) as you set off on the greatest DKC adventure yet! The final showdown with KAOS takes place in a cliff-top laboratory at the End of the World. It could get seriously ugly. Monkey mayhem lives on in this exotic island adventure!' FROM games WHERE igdb_id = 1094 ON CONFLICT (game_id, language_code) DO NOTHING;
