INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jumping-flash-2', 20300, '1996-04-26', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coauc0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3r7y.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumping Flash! 2', 'Need an Action Fix? Get Sky High! Little Muu has been bottled up by the menacing Captain Kabuki. Baron Aloha, once a foe, now turns to friend? Take a flying leap into the wickedly weird world of Robbit and plunge into the wildest 3D gaming experience ever imagined. Single, double and triple-jump your way through a madcap quest-but just when you think it''s over, you take to even newer heights and depths like never seen (or felt) before! * First-person, 360º perspective takes you on a free-falling flight, and the all-new Jump Meter lets you know how high you can go! * Barrel through 12 different fantasy worlds with bonus levels and maximize the fun with all-new underwater 3D environments! * Watch out for a slew of new enemies including the killer, kung-fu gripping, galaxy-ripping Captain Kabuki. * A variety of medals are awarded for different achievements. Can you win them all?!' FROM games WHERE igdb_id = 20300 ON CONFLICT (game_id, language_code) DO NOTHING;
