INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('adidas-power-soccer', 20302, '1996-10-01', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2uki.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adidas Power Soccer', 'Adidas Power Soccer kicks its way onto the PlayStation. You are given a wide variety of gameplay options to choose from, such as season and tournament modes, single games, and multiplayer. When going through the season mode, you can play either a shortened season or an official full-length season. Your team, as well as your opponents, are taken from all over Europe and other countries. If you''re interested in reaching supreme glory at a quicker pace, there is an option for cup battle. Like it implies, you''ll have to beat a certain number of teams in tournament fashion to claim your prize. The game can be played two different ways, arcade or simulation. By choosing the arcade mode, you won''t have to worry about soccer physics or penalties whereas the simulation goes by actual soccer rules. If you lay into someone''s shin, you''ll probably get called for a penalty. Depending on the severity of the penalty, the game will switch to a penalty shot mode, just like real soccer.' FROM games WHERE igdb_id = 20302 ON CONFLICT (game_id, language_code) DO NOTHING;
