INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cutthroat-island', 7828, '1996-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dnb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctnan.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cutthroat Island', 'Based on the feature film of the same name. The game casts players in the role of renegade treasure hunters. The player is able to choose between two characters: Morgan Adams, a female character who wields a rapier; or William Shaw, a buccaneer who is armed with a sword. The game features single player and two player action mode. During single player mode, the player''s character must battle through 10 levels, encountering various foes such as pirates, redcoats and harbor masters. The game features two different gameplay styles to choose from: Swordplay and Brawling. In addition to all the swordplay, level two requires players to flee from prison guards in a quarry cart, and level five puts player atop a runaway horse-drawn carriage. As the player progresses through the game several items such as knives, bombs, bottles, torches, hammers, pistols, and other weapons are collectable.' FROM games WHERE igdb_id = 7828 ON CONFLICT (game_id, language_code) DO NOTHING;
