INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('art-of-fighting-3-the-path-of-the-warrior', 6566, '1996-03-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1zh4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nq4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Art of Fighting 3: The Path of The Warrior', 'In this third and final entry in the Art of Fighting series, the story shifts from Ryo Sakazaki to his best friend and rival, Robert Garcia, as he ventures into Mexico to try and locate Freia Lawrence, a childhood friend, who asked for his help. However, he leaves without the consent of The Garcia Foundation, which sends an agent named Karman Cole to get him back. But not everything is as simple as it looks... because Robert is not the only one looking for Freia. Art of Fighting 3: The Path of The Warrior features ten playable characters with different fighting styles, a completely new fighting system based on joystick and button combinations, and incredibly detailed graphics and animation.' FROM games WHERE igdb_id = 6566 ON CONFLICT (game_id, language_code) DO NOTHING;
