INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wave-race-64', 3629, '1996-09-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa9f0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3zr8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wave Race 64', 'Wave Race 64 is sure to provide some of the most exciting racing you''ve ever experienced. Feel the pounding and crashing of the waves as you accelerate into straight-aways, whip around the marker buoys and go airborne on the jump ramps. Don''t race alone - challenge a friend! Take control in three different modes of play - Championship, Time Trials and Stunt Mode. Nine challenging courses set in exotic locales - race conditions change and the wave action responds to the way both you and your opponents race!' FROM games WHERE igdb_id = 3629 ON CONFLICT (game_id, language_code) DO NOTHING;
