INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadlock: Planetary Conquest', 'In Deadlock, an intense turn-based strategic simulation, seven races colonize a virgin planet, but only one will survive. Build your province’s structures. Conduct research to advance your race. Devise the perfect strategy of diplomacy, intimidation and warfare. Every decision you make will determine the ultimate fate of your people, your empire, and your survival.' FROM games WHERE igdb_id = 10171 ON CONFLICT (game_id, language_code) DO NOTHING;
