INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tail of the Sun', 'Tail of the Sun, known in Japan as Taiyo no Shippo: Wild, Pure, Simple Life, is an action role-playing video game developed by Artdink for the PlayStation. It was created by Kazutoshi Iida, who worked on Aquanaut''s Holiday and would later work with Nintendo on Doshin the Giant. The player''s ultimate objective is to build a tower of mammoth tusks that reaches the sun. To this end, a large map full of various creatures and oddities must be traversed in an effort to locate and gather sufficient food for the tribe to thrive and multiply.' FROM games WHERE igdb_id = 20814 ON CONFLICT (game_id, language_code) DO NOTHING;
