INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'X-Men vs. Street Fighter', 'X-Men vs. Street Fighter is a fighting game originally released as a coin-operated arcade game in 1996. It is Capcom''s third fighting game to feature Marvel Comics characters and the first game to match them against their own, with characters from Marvel''s X-Men franchise being matched against the cast from the Street Fighter series. It was the first game to blend a tag team style of combat with the Street Fighter gameplay, as well as incorporating elements from Capcom''s previous Marvel-themed fighting games, X-Men: Children of the Atom and Marvel Super Heroes.' FROM games WHERE igdb_id = 8244 ON CONFLICT (game_id, language_code) DO NOTHING;
