INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Slug', 'Metal Slug is a 1996 run and gun arcade video game originally developed by Nazca Corporation and released by SNK for the Neo Geo MVS. It is the first installment in the eponymous series. Set in 2028, players assume the role of Peregrine Falcon Strike Force soldiers Marco Rossi and Tarma Roving on a fight against the Rebel Army led by Donald Morden and overthrow his coup d''état to prevent a New World Order.' FROM games WHERE igdb_id = 1404 ON CONFLICT (game_id, language_code) DO NOTHING;
