INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PowerSlave', 'In this first-person shooter, you assume the role of an armed forces specialist dispatched to probe unusual occurrences in the ancient Egyptian city of Karnak. As you delve into the investigation, you discover that alien invaders, with a proclivity for mummifying humans alive, have seized control of the city. Your mission is to navigate through progressively challenging levels, contending with an extraordinary cast of adversaries, to complete the game.' FROM games WHERE igdb_id = 8338 ON CONFLICT (game_id, language_code) DO NOTHING;
