INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('killer-instinct-2', 2930, '1996-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4vdw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scs07v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killer Instinct 2', 'Killer Instinct 2 follows on from the plot line that the previous installment ended with. Eyedol''s death at the hands of Orchid accidentally sets off a time warp, transporting some of the combatants back in time and allowing the Demon Lord Gargos to escape from Limbo. Now, trapped 2000 years in the past, the warriors that survived Killer Instinct, along with several new faces, fight for the right to face Gargos in combat, but Chief Thunder, Cinder and Riptor did not return. Each character that survived the journey from the first game has a corresponding background story, while new characters on this installment are native inhabitants of this past time period. Some fighters, like T.J. Combo who survives from the original, just want to get home. Others, like new character Tusk, want to bring an end to Gargos and his reign of evil. This time there is no tournament or prize money, just a fight to the finish with the fate of the future hanging in the balance.' FROM games WHERE igdb_id = 2930 ON CONFLICT (game_id, language_code) DO NOTHING;
