INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twinkle Star Sprites', 'Twinkle Star Sprites is a 1996 competitive scrolling shooter arcade game originally created by ADK. It was ADK''s last production for the Neo-Geo platform. The gameplay, which can be characterized as a combination of a fixed shooter and a versus puzzle game, uses combinations of shots, as well as timed power-ups to attempt to damage the opponent. These attacks also serve as counters to the opponent''s attack.' FROM games WHERE igdb_id = 35378 ON CONFLICT (game_id, language_code) DO NOTHING;
