INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saturn Bomberman', 'Saturn Bomberman is an action game by Hudson Soft for the Sega Saturn. The twelfth installment in the Bomberman series, it was first released in Japan on July 19, 1996, in Europe in May 1, 1997, and in North America in September 4, 1997. It is best known for its multiplayer functionality for up to ten players using multitaps. It received praise for its gameplay and multiplayer, but criticism for not advancing the Bomberman series enough. Saturn Bomberman can also connect to the Sega Saturn NetLink internet system, allowing two people from opposite ends of the earth to battle it out.' FROM games WHERE igdb_id = 28393 ON CONFLICT (game_id, language_code) DO NOTHING;
