INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Kidou Senki Gundam Wing: Endless Duel', 'It is the year After Colony 195, and war between the Space Colonies and Earth has begun. To give the colonies an edge, they send 5 young soldiers, trained to perfection, to earth in the most powerful of Mobile Suits-Gundams. With their arrival, the tide of the war changes as they battle against the Earth forces and the Colonies of their origin.' FROM games WHERE igdb_id = 42464 ON CONFLICT (game_id, language_code) DO NOTHING;
