INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil', 'Resident Evil is a survival horror classic in which a group of special forces agents, known as S.T.A.R.S, struggle against hordes of zombies and various other mutants in a mysterious mansion as they try to uncover the truth behind the terrifying infection. The gameplay environment consists of polygonal 3D characters placed over pre-rendered 2D backgrounds. As such, the game relies on pre-determined camera angles for a view of the action instead of a real-time camera like most games. The game is credited for coining the phrase "survival horror" and popularizing the genre.' FROM games WHERE igdb_id = 424 ON CONFLICT (game_id, language_code) DO NOTHING;
