INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('m-a-x-mechanized-assault-exploration', 775, '1996-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3mqh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arpp1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'M.A.X.: Mechanized Assault & Exploration', 'Your Mission: colonize new worlds on distant planets. As the Mission Commander, you and the Mechanized Assault & Exploration (M.A.X.) Force you lead are the first ones in. Mining stations, power plants, tactical combat vehicle factories, habitats - it''s up to you to plan and construct them. The entire new colony? You create it. The resources you find there? Control them. Enemies? Crush ''em! And there will be enemies. You''re not the only Mission Commander trying to colonize the planets. You''ll have to push yourself to the limit to survive the ultimate showdown in strategic warfare. It''s espionage, heavy artillery, offensives, counter offensives and intelligence - all with maximum consequences! Features: For ultimate customization control, play as one of eight factions, choose from over 50 land, sea, and air units, upgrade armor, speed, and range. Campaign and custom missions. Simultaneous or turn based game play plus adjustable turn length and game speed will challenge both real-time and turn-based strategy gamers. Any combination of up to four human or computer opponents can wage war.' FROM games WHERE igdb_id = 775 ON CONFLICT (game_id, language_code) DO NOTHING;
