INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lennus-ii-fuuin-no-shito', 38376, '1996-07-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kix.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8r9w.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lennus II: Fuuin no Shito', 'The second game in the Lennus / Paladin''s Quest series. The games development was very troubled and took four years instead of the planned two. Upon release it sold very poorly, even after being promoted through Nintendo Power. This caused the plans for Lennus III to be shelved. The magic system have been expanded to eight spirits representing the elements Fire, Light, Wind, Gold, Earth, Sky, Water and Void. Which can be combined or used separately for a total of 36 spells. Instead of building up a spirit skill rating by using the spells relating to the spirit, in Lennus II you power up the spirits by defeating monsters and earning spirit-specific experience points in addition to the normal experience points. A Nintendo Power version of the game was released in 1997.' FROM games WHERE igdb_id = 38376 ON CONFLICT (game_id, language_code) DO NOTHING;
