INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('privateer-2-the-darkening', 810, '1996-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobony.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21pt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Privateer 2: The Darkening', 'You regain consciousness and the unfamiliar faces surrounding you inform you that you''ve lost your ship in an unfortunate accident. The cutthroat world of the Tri-System privateers greets you with a clenched fist and a knife pointed at your back. Your only order of business is survival. You''ve got just enough credits to afford something resembling a new ship. It takes more than just a bucket of bolts to make it in this world; you''ll need upgrades, and most important of all: money. The sector is brimming with "business" opportunities, but who can you trust? Legal or not, it''s time to trade, travel, and battle your way through a place where high risk equals high reward and only those with the brass reap the rewards. Privateer 2: The Darkening is the premier open universe space trading and combat sim. Blaze your own path through the Tri-System by either hook or crook. Take any mission you see fit, without rules or restrictions. Corner the market as you work out trade routes with the most reward. The universe is waiting for you, Privateer.' FROM games WHERE igdb_id = 810 ON CONFLICT (game_id, language_code) DO NOTHING;
