INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Realms of Arkania III: Shadows over Riva', 'Something sinister lurks in the seaside town of Riva. An evil force has subverted the city''s leaders, and evil things lurk in the town''s sewers. Explore the huge city, dungeons and even underwater regions in stunningly detailed 3D. Adjustable difficulty levels make the game as simple or as detailed as you like.' FROM games WHERE igdb_id = 2498 ON CONFLICT (game_id, language_code) DO NOTHING;
