INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destruction Derby 2', 'Destruction Derby 2 is the sequel to the MS-DOS, PlayStation, Sega Saturn and Nintendo 64 title Destruction Derby. Here, the player must race on up to seven different circuits, in a range of modes, similar to its predecessor. The modes are Wrecking Racing (where the player must destroy or spin the other competitors), Stock Car (a typical race where it''s first to the flag) and Destruction Derby, which is based around the crash arenas. Commentator Paul Page performed as the announcer. This Racing game is widely known for its destruction and chaotic themes that are followed by loud, gritty and dark metal songs.' FROM games WHERE igdb_id = 1170 ON CONFLICT (game_id, language_code) DO NOTHING;
