INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spycraft: The Great Game', 'Enter the World of International Intrigue. It''s you against faceless enemies in a rush to unravel a high-level assassination plot. Arm yourself with authentic spy tools, high-tech weapons and professional skills true to CIA operations. Then confront realistic global scenarios...where decisions you make determine the balance of world power.' FROM games WHERE igdb_id = 2232 ON CONFLICT (game_id, language_code) DO NOTHING;
