INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jagged-alliance-deadly-games', 8, '1996-09-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co29gc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6czl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jagged Alliance: Deadly Games', 'The enemy is on the run. One more mortar shell should take them out. Still, you have to blow up the bridge by sundown, and Postie is starting to talk to himself again. Maybe you shouldn''t let him keep that dynamite... More ways to play. Play the new solo campaign or choose multiplayer mode via your network connection. More power. The included scenario editor provides infinite replay ability. Create your own maps, traps and enemies. Use the campaign editor to create your own deadly games. More mercenaries. Choose from 70 different mercs, including 10 new ones - plus all 60 of the original Jagged Alliance mercs. More weapons. Fun new war toys include mortars, grenade launchers, boobytrap kits and more! More terrain. Skirmish through jungles, deserts, towns and frozen wastelands. And more attitude than ever!' FROM games WHERE igdb_id = 8 ON CONFLICT (game_id, language_code) DO NOTHING;
