INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Green Version', 'Pokémon Green, along with Pokémon Red, are the first video games in the Pokémon series of games. They are the first paired versions of Generation I. Developed over the course of several years, Red and Green established several standards for later Pokémon games and sequels. They take place in the Kanto region, with the player having to collect eight Gym Badges to become the Pokémon Champion while also completing the Pokédex by collecting all 151 Pokémon.' FROM games WHERE igdb_id = 8377 ON CONFLICT (game_id, language_code) DO NOTHING;
