INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Realms of the Haunting', 'Forged in the Beginning and protected by the Seven Seals, there lies a place where thought and creation intertwine. The center for all realms of existence, it is the balancing force between good and evil, man and spirit. A focal point for all energies, and the one element that has kept the consuming nature of darkness at bay... Until now.' FROM games WHERE igdb_id = 844 ON CONFLICT (game_id, language_code) DO NOTHING;
