INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('titanic-adventure-out-of-time', 7516, '1996-11-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2iqx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arrl2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Titanic: Adventure out of Time', 'Titanic: Adventure Out of Time is a computer game developed by Cyberflix. It was published in the United States and Europe by GTE Entertainment and Europress respectively, and released on November 12, 1996. The game is a point-and-click adventure game which sees the player traveling around a virtual representation of the RMS Titanic. Titanic: Adventure Out of Time comes in three versions: a PC, Macintosh, or hybrid version that works on both the Windows and Mac. Version 1.0 of the game is an upgrade of the game from GTE Entertainment to just Cyberflix and is a stability upgrade first released in 1997. It comes in either a threefold CD jacket or a jewel case version. The French and German version of the game comes in two paper sleeves. The Mac and Windows versions were released first, produced by Cyberflix and distributed by GTE Entertainment in 1996. Hybrid versions of the game, which are compatible with both the Mac and Windows operating systems, were distributed and produced by Cyberflix after GTE Entertainment went out of business in 1997. Later versions were distributed by Hammerhead Entertainment, who took over production after Cyberflix also went out of business in 1998. The game is available in seven languages: English, French, German, Dutch, Russian, Polish and Korean. Characters in Titanic: Adventure Out of Time were rendered by way of photographs of actors given limited animation in sync with dialogue. The producers of this game used this same style of rendering for a previous adventure entitled Dust: A Tale of the Wired West.' FROM games WHERE igdb_id = 7516 ON CONFLICT (game_id, language_code) DO NOTHING;
