INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Shodown IV: Amakusa''s Revenge', 'Samurai Shodown IV: Amakusa''s Revenge, also known as Samurai Spirits: Amakusa''s Descent in Japan, is the fourth in SNK''s flagship Samurai Shodown series of fighting games. Chronologically, it is the second and final chapter of a story between Samurai Shodown and Samurai Shodown II, with Samurai Shodown III being the first chapter.' FROM games WHERE igdb_id = 19988 ON CONFLICT (game_id, language_code) DO NOTHING;
