INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Furcadia', 'Furcadia is a fantasy world of magic and creation, alive with adorable animals and mythical creatures. Choose your favorite customizable avatar and start exploring this friendly, user-empowering Online Social Game (MMOSG) with rich player-driven content. Use the free, simple yet powerful tools to build literally anything you can dream up! Whether you enjoy Socializing with friends, Exploring, Creating, or Roleplaying, we invite you to an interactive experience unlike any other. Current Guinness World Record holder for longest running MMO.' FROM games WHERE igdb_id = 18343 ON CONFLICT (game_id, language_code) DO NOTHING;
