INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heretic: Shadow of the Serpent Riders', 'In a twisted medieval dimension, undead creatures and bestial horrors have done the unthinkable--callously slaughtering your entire race. Your friends. Your family. Eliminated. But the nightmare has just begun. Wielding ungodly weapons such as the Firemace and Hellstaff and casting spells from the Tomes of Power, you must seek your vengeance. Or die trying.' FROM games WHERE igdb_id = 8419 ON CONFLICT (game_id, language_code) DO NOTHING;
