INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mad TV 2', 'Broadcast like crazy! Mad TV 2 A classic among fun simulations finally returns. This time, three broadcasting stations set out to flood the living rooms of the world with ridiculous programs. Play as the program director of one of these chaotic channels! - SVGA graphics - Network play - Fully in German - Completely crazy For DOS and Windows 95' FROM games WHERE igdb_id = 92915 ON CONFLICT (game_id, language_code) DO NOTHING;
