INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Realm', 'The Realm was designed to combine the animated visual environments and inventories of Sierra''s point-and-click adventure games with the role-playing mechanisms of MUDs. The game features a high fantasy setting inspired by Dungeons & Dragons and The Lord of the Rings. Gameplay takes place in discrete rooms, which are organized into dungeons, forests and towns.' FROM games WHERE igdb_id = 207001 ON CONFLICT (game_id, language_code) DO NOTHING;
