INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bogey Dead 6', 'A flight simulation video game developed by Pegasus Japan and Bit Town. The game features six real fighter planes: the F-4E, F-14D, F-15E, F-16C, F/A-18E and the F-22 Raptor. The game is played from the perspective of an ace pilot for the United States Air Force. The objective is to protect the United States from communist invasion, enemy involvement and terrorism.' FROM games WHERE igdb_id = 20590 ON CONFLICT (game_id, language_code) DO NOTHING;
