INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-22 Lightning II', 'The next generation of the U.S. Air Force''s air superiority fighter is reproduced with incredible realism and impressive graphics in this unparalleled game that also offers the possibility of multi-player games. The Lockheed F-22 is an incredible technical marvel: space-age technologies have been employed to produce a fighter with stealth characteristics, the ability to travel the supercruise. Multiplayer mode, new Polygon Engine, SVGA with 3 different graphics resolutions, four Landscapes: desert, jungle, island and coastal area. 16-bit Dolby surround sound. Footage of F-22 in action. Accurate cockpit and instrumentation images. More than 36 missions.' FROM games WHERE igdb_id = 10759 ON CONFLICT (game_id, language_code) DO NOTHING;
