INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Truck Madness', 'One of the best selling auto-racing games on the PC comes to Game Boy Advance with a variety of vehicles and tracks for the some stompin'' good fun on the go. Get behind the steering wheel of the world''s most powerful vehicles as they crush, splatter, jump, and roll their way to victory.' FROM games WHERE igdb_id = 6513 ON CONFLICT (game_id, language_code) DO NOTHING;
