INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Queensrÿche''s Promised Land', 'Promised Land is a multimedia adventure game based around the members of the progressive-rock band Queensrÿche. The game is a 2-CD set, the game fills up the first one, and in the second you''ll find mini-documentaries and music videos.' FROM games WHERE igdb_id = 71465 ON CONFLICT (game_id, language_code) DO NOTHING;
