INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wayne-gretzky-s-3d-hockey', 3630, '1996-10-01', 71, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cca.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wayne Gretzky''s 3D Hockey', 'As opposed to the more realistic hockey gameplay seen in Electronic Arts'' NHL series, the game featured a more unrealistic arcade-style of gameplay, featuring moves such as "power saves", which caused the goaltender to briefly transform into a brick wall, "power shots", which would set the net on fire or knock the goalie into the net, and "power checks", which would send an ambulance across the top of the screen. It featured high-scoring games and over-the-top fights. There was also a simulation mode for those looking for more realistic gameplay. The game allowed the creation of profiles and would keep track of important individual and team stats, including goals, assists, and wins, among others.' FROM games WHERE igdb_id = 3630 ON CONFLICT (game_id, language_code) DO NOTHING;
