INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('soultrap', 62373, '1996-11-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coap7c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sczvnz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SoulTrap', 'SoulTrap is a 3D platform game that takes place inside the mind of the main character of the game: Malcolm West. The fears and anxieties of Malcolm West are represented by strange often moving platform structures high in the sky. The player has to jump from platform to platform, shooting phobias taking the form of enemies and outwitting obstacles that he comes across. The game comes with 11 levels with each their own graphical theme. The player can find various weapons such as a magical axe, a .45 automatic and a grenade launcher. There are also power-ups that allow the player to replenish health and ammunition. The game allows the use of both first person and third person camera angles.' FROM games WHERE igdb_id = 62373 ON CONFLICT (game_id, language_code) DO NOTHING;
