INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rage Racer', 'Rage Racer is the third title in the Ridge Racer series of racing games. For the first time in series, Rage Racer introduces a brand new advanced single player career system which uses credits that player can get after winning races, then it can be used to buy or upgrade cars.' FROM games WHERE igdb_id = 18698 ON CONFLICT (game_id, language_code) DO NOTHING;
