INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kichikuou Rance', 'Kichikuou Rance (literally translating to "Brutal King Rance") is the seventh game in Alicesoft''s flagship Rance Series. It was released in Japan on December 19, 1996. It was the first Alicesoft game to be produced for Windows 95 operating systems, as well as the first game to use the company''s SYSTEM 35 engine and the territory conquest strategy gameplay used in several of its future releases.' FROM games WHERE igdb_id = 132645 ON CONFLICT (game_id, language_code) DO NOTHING;
