INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Actua Golf', 'Actua Golf is a golf simulation with full 3D terrain and characters. It comes with two courses to play at (country and tropical), customizable characters and multi-view shot tracking and action replays. Actua Golf uses similar game controls as older golf titles did. With a swing meter, where you have to time correctly to hit the ball right.' FROM games WHERE igdb_id = 45497 ON CONFLICT (game_id, language_code) DO NOTHING;
