INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duck Hunt 2', 'Tucked down into your blind just off of the river you and your hunting'' dog "JAZZ" are ready to take some waterfowl home for dinner. A 12 gauge shotgun is the gun that will bring down these ducks. It''s the crack of dawn and the ducks are moving, coming in from the right, left, and off of the water. You''re are sure to have plenty to shoot at. Not to mention you don''t have to get up at 4:00 in the morning.' FROM games WHERE igdb_id = 127992 ON CONFLICT (game_id, language_code) DO NOTHING;
