INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Adventures of Lomax', 'Lomax is in way over his head. Evil Ed has nabbed his pals and tricked them into doing diabolical deeds. Only Lomax has the power to break the sinister hex! Leap into action with Lomax as he battles Ed''s evildoers and travels through bizarre lands in this fast and frantic thriller!' FROM games WHERE igdb_id = 7663 ON CONFLICT (game_id, language_code) DO NOTHING;
