INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shellshock', 20635, '1996-02-01', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gvt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmeu1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shellshock', 'Having served in combat for the United States, Da Wardenz are out for one thing -- justice. This anti-terrorist tank force was conceived after an ill-fated campaign at Mostvia Vatska in 1994. Coming under heavy fire, the troops sent a distress signal to the U.S. Intelligence requesting immediate backup. The government turned their backs on the Special Forces unit by making them expendable and refusing to send in backup. As a result, five men survived; those five men formed Da Wardenz. Here''s where you come into play. Assuming the role of a rookie commando, your mission is simple: prove yourself to Da Wardenz by destroying terrorist forces and rectifying global corruption. Easy, huh? That''s not all -- you''ll be in command of an M-13 Predator battle tank; this thing can mow down forests and calm any terrorist dispute. Along the way, you can upgrade your tank in armaments and shielding. Shellshock is broken into two parts: The Pen and actual mission objectives. As Da Wardenz headquarters, The Pen has all sorts of locations including the main hangar, basketball court, simulation room, workshop area, briefing area, and various lockers. Before a mission, you''ll want to explore the headquarters and interact with each member of the team; you may learn something. When you''re ready to kick some terrorist butt, you''ll simply walk to the tank area and hop in!' FROM games WHERE igdb_id = 20635 ON CONFLICT (game_id, language_code) DO NOTHING;
