INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: The Legend', 'Dragon Ball Z: Legends is a fighting game which utilizes a unique system of play that is different from most other fighters. The graphics feature 2-D sprites in a three dimensional world. Although each battle begins on the ground, the majority of the action is featured skyward. The story mode of the game is divided into episodes, and it encompasses all of Dragon Ball Z, featuring the most important battles of the series.' FROM games WHERE igdb_id = 2579 ON CONFLICT (game_id, language_code) DO NOTHING;
