INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('radical-dreamers-le-tresor-interdit', 1803, '1996-02-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4hbm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8aru.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Radical Dreamers: Le Trésor Interdit', 'Radical Dreamers is the little-known sequel to the popular and critically acclaimed Chrono Trigger. Unlike Chrono Trigger and the other games in the Chrono series, Radical Dreamers is a menu-driven text adventure/visual novel, with sparse visuals and atmospheric music. The game was released only in Japan for the Super Famicom''s Satellaview satellite radio service. In this game, three thieves - Kid, a young girl famous for her age, Magil, a mysterious wizard with an unknown past, and Serge, a rather cowardly young man - head to Lord Lynx''s manor to steal the Frozen Flame, a legendary jewel. But Kid''s not just there for the jewel - she has a personal vendetta against Lynx. Many elements from this game were carried over to Chrono Cross, including characters, music, and parts of the story. In fact, Chrono Cross implies Radical Dreamers takes place in one of many alternate versions of the main game world. The game was later localized and bundled in the remaster Chrono Cross: The Radical Dreamers Edition, under the newly localized title of "Radical Dreamers: Le Trésor Interdit".' FROM games WHERE igdb_id = 1803 ON CONFLICT (game_id, language_code) DO NOTHING;
