INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Delisoba Deluxe', 'A driving/racing game for Sega Saturn developed by CAVE and TBS Television. It was made as a tie-in to TBS''s mid-1990s Japanese game show Tokyo Friend Park, where one of the games, Delisoba ("delivery soba"), had celebrities command a virtual motorcycle trying to deliver soba to the TBS TV Studios. Deluxe is a "port" of this game to the Saturn, which adds features such as a time attack and track editor, and was not sold in stores, but rather given away at the show (either to winners or to audience members, exactly what is unknown).' FROM games WHERE igdb_id = 213864 ON CONFLICT (game_id, language_code) DO NOTHING;
