INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '19XX: The War Against Destiny', '19XX: The War Against Destiny is a vertical scrolling shooter arcade game made by Capcom in 1995 (copyrighted in 1996). The game is the 4th of a series of World War II vertical shooters made by Capcom. The story takes place before a fictional war (Hence, the 19XX) as a lone pilot tries to defeat an entire army/evil organization from starting another World War, which soon escalates to a nuclear apocalypse.' FROM games WHERE igdb_id = 6078 ON CONFLICT (game_id, language_code) DO NOTHING;
