INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snoopy''s Campfire Stories', 'Snoopy''s Campfire Stories is an educational PC-rom game for Windows and Macintosh featuring characters from the Peanuts comic strip by Charles M. Schulz. It was released in 1996, developed by Morgan Interactive Inc. and published by Virgin Sound and Vision. The game features the Peanuts gang sitting around a campfire, telling stories to each other and writing a letter about their day at camp afterwards. Players can play as five different characters from the Peanuts gang with their own storyline and activities including cooking, fishing and photography.' FROM games WHERE igdb_id = 73624 ON CONFLICT (game_id, language_code) DO NOTHING;
