INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Yahtzee', 'A computer adaptation of the classic dice game Yahtzee. Players take turns throwing five dice and attempting to make scoring combinations (full house, straight). The elusive five of a kind is referred to as a Yahtzee (hence the game''s name).' FROM games WHERE igdb_id = 69218 ON CONFLICT (game_id, language_code) DO NOTHING;
