INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Larax & Zaco', 'An unconventional platform game. Besides collecting of bonuses, you must destroy buildings and platforms in the playin by smartly placing bombs. You can use small, harmless bombs or mor ones (four types are available) and enjoy yourself watching huge constructions explode in thousands of small pieces. Double screen with two simultaneous players, Italian and English language available.' FROM games WHERE igdb_id = 129402 ON CONFLICT (game_id, language_code) DO NOTHING;
