INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ace Ventura', 'Wouldn’t it be cool if there was a world where people actually paid you to hang out with beautiful women and rescue kidnapped animals? Where ugly tropical shirts were still in fashion? Where obnoxious behavior was admired and even rewarded? Well, my jungle friends, there is. It’s the word of Ace Ventura, and only a loo-OOO-ooo-ooo-ser would NOT go in there.' FROM games WHERE igdb_id = 4586 ON CONFLICT (game_id, language_code) DO NOTHING;
