INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Krazy Ivan', 'It is the year 2018. Devastating energy shields have appeared in five different places on the earth and are spreading at an incredible rate. There is only one solution: combat the enemy from within and destroy them. Only one machine is powerful enough: a 40ft high Robot. Only one man is crazy enough to operate it. His name: Krazy Ivan.' FROM games WHERE igdb_id = 20604 ON CONFLICT (game_id, language_code) DO NOTHING;
