INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('treasure-hunter-g', 15844, '1996-05-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9712.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/u1v5w35axkqyzqiv7x6t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Treasure Hunter G', 'Brothers Red and Blue G. decide to leave their idyllic village in search of their long lost father, who left the kids years ago to go treasure hunting. Unfortunately, as soon as they begin their quest, they become entangled with a mysterious girl on the run from evil monsters who holds the key to the resurrection of a great demon. Now its up to the brothers to save the world if they ever want to find their father. Treasure Hunter G is a top-down RPG in which you control your party of four characters as they explore the fantasy/sci-fi game world in search for quests and grinding their stats while the plot advances. The game is divided in a world-map screen, a top-down "town" mode and a turn-based fight mode in which the characters are taken to generic tiled top-down arenas in which they select each character and move or attack depending on their action points. Enemies can be seen on the map instead of jumping at you at random intervals, and you can freely decide whether to engage them or simply circle them around. The game uses a combination of hand-drawn sprites and CGI pre-rendered one (mostly for the main characters) with a distinct cute or Super Deformed design (as usual for most console RPGs).' FROM games WHERE igdb_id = 15844 ON CONFLICT (game_id, language_code) DO NOTHING;
