INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dungeons-and-dragons-shadow-over-mystara', 10253, '1996-12-31', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25p3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7dj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeons & Dragons: Shadow over Mystara', 'In addition to the original four heroes found in its predecessor, Dungeons & Dragons: Tower of Doom (Cleric, Dwarf, Elf and Fighter), Shadow of Mystara adds a Thief and a Magic-User to the selection. Furthermore, with the inclusion of two separate versions of each character''s sprite set, the game allows up to two players to select the same character (in Tower of Doom each of the characters could only be selected once), effectively giving the game 12 "different" characters to choose from. The two Clerics and two Magic Users also have subtle differences within their spell books. The controls are using four buttons: Attack, Jump, Select (brings up a small inventory ring around the character allowing the player to choose what item is set in the Use slot) and Use. The Cleric, Elf and Magic-User also have two extra rings for their spells, with the Jump button used to switch from ring to ring. While the game uses the same kick harness as the previous game, the Select and Use buttons are reversed. Shadow over Mystara also introduced a selection of special moves which are executed by moving the joystick and tapping the buttons in certain combinations, in a way similar to the Street Fighter series. The characters (except for the Magic-User) have a Dashing Attack as well as a Rising Attack which can be used to combo monsters or even juggle them in the air. Most characters (again, with the exception of the Magic-User and also Cleric) also have a Megacrush, a move common to nearly all of Capcom side-scrollers, which damages all enemies standing close enough to the character but in turn also damaging the player themselves.' FROM games WHERE igdb_id = 10253 ON CONFLICT (game_id, language_code) DO NOTHING;
