INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Triple Play 97', 'An early 3D baseball video game developed by EA Sports (PS1) and Synergistic Software (PC port). MLB and MLBPA licensed. Opening day 1996 team rosters and schedules. All 28 Major League Baseball parks, 3D-modeled and with slick intro cinematics for each showing the camera flying down into the park from above. Informative play-by-play color commentary. Multiplayer with up to 8 players is possible with two Multitaps on the PlayStation version or up to 6 players on the PC version via modem connection or Gravis gamepads. Gameplay modes include Exhibition, Series, All-Star, Playoffs, Season, and Home Run Derby.' FROM games WHERE igdb_id = 20649 ON CONFLICT (game_id, language_code) DO NOTHING;
