INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Holiday Island', 'Holiday Island is a business simulation video game developed by German game design company Sunflowers. Most of the gameplay involves juggling funds to build hotels, accommodation, leisure activities and restaurants. The number and location of these is important, as is the interconnectivity between different facilities.' FROM games WHERE igdb_id = 7766 ON CONFLICT (game_id, language_code) DO NOTHING;
