INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pilotwings 64', 'Forget about those other flying games. This is the ultimate flight experience! Pilotwings 64 carries you off into a vast three-dimensional environment. Pilot several different vehicles and take in breathtaking sights. Successfully complete flight tests to earn your flight badge. Get a high enough score, and you’ll get a chance at bonus games such as Cannonball and Sky Diving! Soar into a wild blue yonder with Pilotwings 64!' FROM games WHERE igdb_id = 3573 ON CONFLICT (game_id, language_code) DO NOTHING;
