INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assault Rigs', 'Do you have what it takes to be the next World Net Champion? Grab the controls of the Zam Cam Assault Rig and enter the cyber combat zone of the future! Conquer arena after arena filled with skyways, trenches, pushblocks and a whole host of enemies waiting to blow you to smithereens. To the victor goes the glory in this futuristic super-sport where there is no second place!' FROM games WHERE igdb_id = 15476 ON CONFLICT (game_id, language_code) DO NOTHING;
