INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('grid-runner', 20738, '1996-10-31', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2xd9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7qn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grid Runner', 'Grid Runner is a futuristic version of "tag." On offense, your objective is to capture the flags around the levels without being tagged or killed. On defense, your main objective is to tag the other player (either the computer or a friend in two-player mode) before he or she collects all the flags.  In each level you will find different colored balls that will help you defeat your enemies. For example, the green balls increase your speed, red increases your magic, and blue increases your agility. The more power-ups you collect, the more efficient you become. You can also use and collect magic points.  Collecting magic points allows you to do one of six things: build a temporary bridge, drop explosives behind you, slow down your opponent, fire a weapon (which can be upgraded or traded), temporarily boost your speed, or teleport out of danger.' FROM games WHERE igdb_id = 20738 ON CONFLICT (game_id, language_code) DO NOTHING;
