INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bust-A-Move 3', 'The second sequel to Puzzle Bobble. It was released into arcades in September 1996 and later ported to the Sega Saturn, Sony PlayStation, Game Boy, Nintendo 64 and Microsoft Windows. It would be the final appearance of Puzzle Bobble on the Sega Saturn. Like its predecessors, the player is tasked with shooting balls at groups of balls, creating groups of 3 or more, which are then removed from play. A European remake is entitled Bust-a-Move 3 DX. released in America as Bust-a-Move ''99.' FROM games WHERE igdb_id = 3454 ON CONFLICT (game_id, language_code) DO NOTHING;
