INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bugs Bunny in Double Trouble', 'BUGS BUNNY has dreamed his way into double trouble. A Mad Scientist is after Bugs'' brain! To escape, bugs must use the Scientist''s Televisor to travel through dreamland and outwit his LOONEY TUNES pals, including DAFFY DUCK, ELMER FUDD, and YOSEMITE SAM. But Bugs'' nightmare doesn''t end there. Before he can rest, Bugs must rocket to Mars to battle MARVIN THE MARTIAN and his trusty dog K-9. Move fast or... "That''s all Folks!"' FROM games WHERE igdb_id = 3052 ON CONFLICT (game_id, language_code) DO NOTHING;
