INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iron Man and X-O Manowar in Heavy Metal', 'Metal titans, Iron Man and X-O Manowar, come together for the first time ever to tackle one heavy-duty cosmic crisis! It''s an apocalyptic meltdown of furious action, with the ultimate in Super Hero power and realism! Featuring Bi-Directional firepower, Chest-Beam blasts, multi-hit combos and Z-axis shooting, ultimate boss battles and enhanced weapon power!' FROM games WHERE igdb_id = 20660 ON CONFLICT (game_id, language_code) DO NOTHING;
