INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('albert-odyssey-legend-of-eldean', 15021, '1996-08-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3z93.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Albert Odyssey: Legend of Eldean', 'Albert Odyssey: Legend of Eldean is a role-playing video game developed by Sunsoft for the Super Nintendo, but cancelled and ported to the Sega Saturn. It is the first Albert Odyssey title to be released in English, as well as the first to feature traditional turn-based role-playing elements as opposed to tactical, strategy-based gameplay. Legend of Eldean was created as a "gaiden", or sidestory to the original titles, and contains back story, characters, and plot that are independent from earlier games in the series. The North American version received generally favorable reviews, with the game''s translation invoking mixed criticism both for its overly-humorous tone and departure from the original Japanese dialogue.' FROM games WHERE igdb_id = 15021 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 15021 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
